<meta name="component" content="WorldCrowdPage">

<!-- The stress page: three hostile nameplates bunched together (one with a
     long name, title and cast) that declutter, one past its maxDistance
     (hidden), twenty-four overhead bars, ten damage numbers at once, long
     loot, prompt, bubble and waypoint labels, a disabled prompt, an
     invalid path, a ring and a line telegraph. -->
<div id="World">
  <Nameplate entity={$nameplate_default.entity} at={$nameplate_default.at} height={$nameplate_default.height} name={$nameplate_default.name} title={$nameplate_default.title} level={$nameplate_default.level} reaction={$nameplate_default.reaction} health={$nameplate_default.health} shield={$nameplate_default.shield} castName={$nameplate_default.castName} castProgress={$nameplate_default.castProgress} icon={$nameplate_default.icon} boss={$nameplate_default.boss} targeted={$nameplate_default.targeted} maxDistance={$nameplate_default.maxDistance} />
  <Nameplate entity={$nameplate_overflow.entity} at={$nameplate_overflow.at} height={$nameplate_overflow.height} name={$nameplate_overflow.name} title={$nameplate_overflow.title} level={$nameplate_overflow.level} reaction={$nameplate_overflow.reaction} health={$nameplate_overflow.health} shield={$nameplate_overflow.shield} castName={$nameplate_overflow.castName} castProgress={$nameplate_overflow.castProgress} icon={$nameplate_overflow.icon} boss={$nameplate_overflow.boss} targeted={$nameplate_overflow.targeted} maxDistance={$nameplate_overflow.maxDistance} />
  <Nameplate entity={$nameplate_cluster.entity} at={$nameplate_cluster.at} height={$nameplate_cluster.height} name={$nameplate_cluster.name} title={$nameplate_cluster.title} level={$nameplate_cluster.level} reaction={$nameplate_cluster.reaction} health={$nameplate_cluster.health} shield={$nameplate_cluster.shield} castName={$nameplate_cluster.castName} castProgress={$nameplate_cluster.castProgress} icon={$nameplate_cluster.icon} boss={$nameplate_cluster.boss} targeted={$nameplate_cluster.targeted} maxDistance={$nameplate_cluster.maxDistance} />
  <Nameplate entity={$nameplate_far.entity} at={$nameplate_far.at} height={$nameplate_far.height} name={$nameplate_far.name} title={$nameplate_far.title} level={$nameplate_far.level} reaction={$nameplate_far.reaction} health={$nameplate_far.health} shield={$nameplate_far.shield} castName={$nameplate_far.castName} castProgress={$nameplate_far.castProgress} icon={$nameplate_far.icon} boss={$nameplate_far.boss} targeted={$nameplate_far.targeted} maxDistance={$nameplate_far.maxDistance} />
  <LootLabel entity={$lootLabel_overflow.entity} at={$lootLabel_overflow.at} height={$lootLabel_overflow.height} name={$lootLabel_overflow.name} count={$lootLabel_overflow.count} rarity={$lootLabel_overflow.rarity} />
  <InteractionPrompt entity={$interactionPrompt_disabled.entity} at={$interactionPrompt_disabled.at} height={$interactionPrompt_disabled.height} action={$interactionPrompt_disabled.action} verb={$interactionPrompt_disabled.verb} name={$interactionPrompt_disabled.name} disabled={$interactionPrompt_disabled.disabled} reason={$interactionPrompt_disabled.reason} maxDistance={$interactionPrompt_disabled.maxDistance} />
  <InteractionPrompt entity={$interactionPrompt_overflow.entity} at={$interactionPrompt_overflow.at} height={$interactionPrompt_overflow.height} action={$interactionPrompt_overflow.action} verb={$interactionPrompt_overflow.verb} name={$interactionPrompt_overflow.name} disabled={$interactionPrompt_overflow.disabled} reason={$interactionPrompt_overflow.reason} maxDistance={$interactionPrompt_overflow.maxDistance} />
  <Waypoint entity={$waypoint_overflow.entity} at={$waypoint_overflow.at} height={$waypoint_overflow.height} kind={$waypoint_overflow.kind} icon={$waypoint_overflow.icon} label={$waypoint_overflow.label} distance={$waypoint_overflow.distance} units={$waypoint_overflow.units} />
  <Waypoint entity={$waypoint_offscreen.entity} at={$waypoint_offscreen.at} height={$waypoint_offscreen.height} kind={$waypoint_offscreen.kind} icon={$waypoint_offscreen.icon} label={$waypoint_offscreen.label} distance={$waypoint_offscreen.distance} units={$waypoint_offscreen.units} />
  <SpeechBubble entity={$speechBubble_shout.entity} at={$speechBubble_shout.at} height={$speechBubble_shout.height} speaker={$speechBubble_shout.speaker} text={$speechBubble_shout.text} shout={$speechBubble_shout.shout} />
  <SpeechBubble entity={$speechBubble_overflow.entity} at={$speechBubble_overflow.at} height={$speechBubble_overflow.height} speaker={$speechBubble_overflow.speaker} text={$speechBubble_overflow.text} shout={$speechBubble_overflow.shout} />
  <SelectionRing entity={$selectionRing_segmented.entity} at={$selectionRing_segmented.at} radius={$selectionRing_segmented.radius} reaction={$selectionRing_segmented.reaction} hover={$selectionRing_segmented.hover} segmented={$selectionRing_segmented.segmented} />
  <Telegraph entity={$telegraph_ring.entity} at={$telegraph_ring.at} shape={$telegraph_ring.shape} radius={$telegraph_ring.radius} inner={$telegraph_ring.inner} angle={$telegraph_ring.angle} width={$telegraph_ring.width} direction={$telegraph_ring.direction} progress={$telegraph_ring.progress} friendly={$telegraph_ring.friendly} />
  <Telegraph entity={$telegraph_line.entity} at={$telegraph_line.at} shape={$telegraph_line.shape} radius={$telegraph_line.radius} inner={$telegraph_line.inner} angle={$telegraph_line.angle} width={$telegraph_line.width} direction={$telegraph_line.direction} progress={$telegraph_line.progress} friendly={$telegraph_line.friendly} />
  <PathLine at={$pathLine_invalid.at} size={$pathLine_invalid.size} path={$pathLine_invalid.path} reach={$pathLine_invalid.reach} endX={$pathLine_invalid.endX} endY={$pathLine_invalid.endY} label={$pathLine_invalid.label} invalid={$pathLine_invalid.invalid} />
  <DamageNumbers hits={$damageNumbers_crowd_hits} />
  <OverheadBars bars={$overheadBars_crowd_bars} height={$overheadBars_crowd.height} />
</div>

<style>
#World { width: stretch; height: stretch; }
</style>
